@CrossOrigin
@RestController
@RequestMapping("/EnterpriseQuery")
public class EnterpriseQueryRestController extends BaseSpringRestController {
	
	public EnterpriseQueryRestController( EnterpriseService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Enterprise using a UUID
     * @param		UUID enterpriseId
     * @return		Enterprise
     */    
    @GetMapping("/load")
    public Enterprise load( @RequestParam(required=true) UUID enterpriseId ) {
    	Enterprise entity = null;

    	try {  
    		entity = service.getEnterprise( new EnterpriseFetchOneSummary( enterpriseId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Enterprise using Id " + enterpriseId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Enterprise business objects
     * @return		Set<Enterprise>
     */
    @GetMapping("/")
    public List<Enterprise> loadAll() {                
    	List<Enterprise> enterpriseList = null;
        
    	try {
            // load the Enterprise
            enterpriseList = service.getAllEnterprise();
            
            if ( enterpriseList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Enterprises" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Enterprises ", exc );
        	return null;
        }

        return enterpriseList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Enterprise enterprise = null;
    protected EnterpriseService service = null;
    private static final Logger LOGGER = Logger.getLogger(EnterpriseQueryRestController.class.getName());
    
}
